import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.1
.target sm_89
.address_size 64

.visible .entry convtrans3d_fwd(
    .param .u64 p_x,
    .param .u64 p_w,
    .param .u64 p_b,
    .param .u64 p_y,
    .param .u32 pN,
    .param .u32 pCin,
    .param .u32 pCout,
    .param .u32 pD,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pDo,
    .param .u32 pHo,
    .param .u32 pWo,
    .param .u32 pK,
    .param .u32 pStride,
    .param .u32 pPad,
    .param .u32 pOutPad,
    .param .u32 pGroups,
    .param .u32 pBiasPresent
)
{
    .reg .pred  %p<17>;
    .reg .b32   %r<128>;
    .reg .b64   %rd<64>;
    .reg .f32   %f<8>;

    // Load pointers
    ld.param.u64 %rd1, [p_x];
    ld.param.u64 %rd2, [p_w];
    ld.param.u64 %rd3, [p_b];
    ld.param.u64 %rd4, [p_y];

    // Load scalars
    ld.param.u32 %r10, [pN];
    ld.param.u32 %r11, [pCin];
    ld.param.u32 %r12, [pCout];
    ld.param.u32 %r13, [pD];
    ld.param.u32 %r14, [pH];
    ld.param.u32 %r15, [pW];
    ld.param.u32 %r16, [pDo];
    ld.param.u32 %r17, [pHo];
    ld.param.u32 %r18, [pWo];
    ld.param.u32 %r19, [pK];
    ld.param.u32 %r20, [pStride];
    ld.param.u32 %r21, [pPad];
    ld.param.u32 %r22, [pOutPad]; // unused, but kept for signature
    ld.param.u32 %r23, [pGroups];
    ld.param.u32 %r24, [pBiasPresent];

    // Thread indices
    mov.u32 %r30, %tid.x;
    mov.u32 %r31, %ntid.x;
    mov.u32 %r32, %ctaid.x;
    mad.lo.u32 %r33, %r32, %r31, %r30;    // w_out

    mov.u32 %r34, %ctaid.y;               // h_out
    mov.u32 %r35, %ctaid.z;               // linear over (n, oc, od)

    // Bounds checks for w and h and z-linear
    setp.ge.u32 %p0, %r33, %r18; @%p0 bra RET;
    setp.ge.u32 %p1, %r34, %r17; @%p1 bra RET;

    mul.lo.u32 %r36, %r10, %r12;          // N * Cout
    mul.lo.u32 %r37, %r36, %r16;          // N * Cout * Do
    setp.ge.u32 %p2, %r35, %r37; @%p2 bra RET;

    // Decompose linear index into (n, oc, od)
    rem.u32 %r40, %r35, %r16;             // od
    div.u32 %r41, %r35, %r16;             // tmp = linear / Do
    rem.u32 %r42, %r41, %r12;             // oc
    div.u32 %r43, %r41, %r12;             // n

    // Prepare group math
    div.u32 %r50, %r11, %r23;             // Cin_g
    div.u32 %r51, %r12, %r23;             // Cout_g
    div.u32 %r52, %r42, %r51;             // g = oc / Cout_g
    mul.lo.u32 %r53, %r52, %r51;          // g * Cout_g
    sub.s32 %r54, %r42, %r53;             // oc within group
    mul.lo.u32 %r55, %r52, %r50;          // ic_start = g * Cin_g
    add.u32 %r56, %r55, %r50;             // ic_end = ic_start + Cin_g

    // Accumulator
    mov.f32 %f0, 0f00000000;

    // ic loop
    mov.u32 %r60, %r55;
L_ic_loop:
    setp.ge.u32 %p3, %r60, %r56;
    @%p3 bra L_ic_done;

    // kd loop
    mov.u32 %r61, 0;
L_kd_loop:
    setp.ge.u32 %p4, %r61, %r19;
    @%p4 bra L_kd_done;

    // td = od + pad - kd
    add.u32 %r62, %r40, %r21;
    sub.s32 %r63, %r62, %r61;

    rem.s32 %r64, %r63, %r20;
    setp.ne.s32 %p5, %r64, 0;
    @%p5 bra L_next_kd;

    div.s32 %r65, %r63, %r20;             // id
    setp.lt.s32 %p6, %r65, 0;
    @%p6 bra L_next_kd;
    setp.ge.s32 %p7, %r65, %r13;
    @%p7 bra L_next_kd;

    // kh loop
    mov.u32 %r66, 0;
L_kh_loop:
    setp.ge.u32 %p8, %r66, %r19;
    @%p8 bra L_kh_done;

    add.u32 %r67, %r34, %r21;
    sub.s32 %r68, %r67, %r66;             // th

    rem.s32 %r69, %r68, %r20;
    setp.ne.s32 %p9, %r69, 0;
    @%p9 bra L_next_kh;

    div.s32 %r70, %r68, %r20;             // ih
    setp.lt.s32 %p10, %r70, 0;
    @%p10 bra L_next_kh;
    setp.ge.s32 %p11, %r70, %r14;
    @%p11 bra L_next_kh;

    // kw loop
    mov.u32 %r71, 0;
L_kw_loop:
    setp.ge.u32 %p12, %r71, %r19;
    @%p12 bra L_kw_done;

    add.u32 %r72, %r33, %r21;
    sub.s32 %r73, %r72, %r71;             // tw

    rem.s32 %r74, %r73, %r20;
    setp.ne.s32 %p13, %r74, 0;
    @%p13 bra L_next_kw;

    div.s32 %r75, %r73, %r20;             // iw
    setp.lt.s32 %p14, %r75, 0;
    @%p14 bra L_next_kw;
    setp.ge.s32 %p15, %r75, %r15;
    @%p15 bra L_next_kw;

    // Load x[n, ic, id, ih, iw]
    // t0 = n * Cin + ic
    mul.lo.u32 %r80, %r43, %r11;
    add.u32    %r80, %r80, %r60;
    // t1 = t0 * D + id
    mul.lo.u32 %r81, %r80, %r13;
    add.u32    %r81, %r81, %r65;
    // t2 = t1 * H + ih
    mul.lo.u32 %r82, %r81, %r14;
    add.u32    %r82, %r82, %r70;
    // t3 = t2 * W + iw
    mul.lo.u32 %r83, %r82, %r15;
    add.u32    %r83, %r83, %r75;

    mul.wide.u32 %rd10, %r83, 4;
    add.s64      %rd11, %rd1, %rd10;
    ld.global.f32 %f1, [%rd11];

    // Load w[ic, ocg, kd, kh, kw] with weight layout (Cin, Cout_g, K, K, K)
    mul.lo.u32 %r84, %r60, %r51;          // ic * Cout_g
    add.u32    %r84, %r84, %r54;          // + ocg
    mul.lo.u32 %r85, %r84, %r19;          // * k + kd
    add.u32    %r85, %r85, %r61;
    mul.lo.u32 %r86, %r85, %r19;          // * k + kh
    add.u32    %r86, %r86, %r66;
    mul.lo.u32 %r87, %r86, %r19;          // * k + kw
    add.u32    %r87, %r87, %r71;

    mul.wide.u32 %rd12, %r87, 4;
    add.s64      %rd13, %rd2, %rd12;
    ld.global.f32 %f2, [%rd13];

    // Accumulate
    fma.rn.f32 %f0, %f1, %f2, %f0;

L_next_kw:
    add.u32 %r71, %r71, 1;
    bra L_kw_loop;
L_kw_done:

L_next_kh:
    add.u32 %r66, %r66, 1;
    bra L_kh_loop;
L_kh_done:

L_next_kd:
    add.u32 %r61, %r61, 1;
    bra L_kd_loop;
L_kd_done:

    add.u32 %r60, %r60, 1;
    bra L_ic_loop;
L_ic_done:

    // Add bias if present
    setp.eq.u32 %p16, %r24, 0;
    @%p16 bra L_skip_bias;
    mul.wide.u32 %rd14, %r42, 4;
    add.s64      %rd15, %rd3, %rd14;
    ld.global.f32 %f3, [%rd15];
    add.f32 %f0, %f0, %f3;
L_skip_bias:

    // Store y[n, oc, od, h, w]
    mul.lo.u32 %r90, %r43, %r12;          // n * Cout
    add.u32    %r90, %r90, %r42;          // + oc
    mul.lo.u32 %r91, %r90, %r16;          // * Do + od
    add.u32    %r91, %r91, %r40;
    mul.lo.u32 %r92, %r91, %r17;          // * Ho + h
    add.u32    %r92, %r92, %r34;
    mul.lo.u32 %r93, %r92, %r18;          // * Wo + w
    add.u32    %r93, %r93, %r33;

    mul.wide.u32 %rd16, %r93, 4;
    add.s64      %rd17, %rd4, %rd16;
    st.global.f32 [%rd17], %f0;

RET:
    ret;
}
"""

_ptx_module = None

