    _get_ptx_module().function("convtrans3d_fwd")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1, padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        assert x.is_cuda, "Input must be on CUDA device"
        weight = self.conv_transpose3d.weight
        bias = self.conv_transpose3d.bias
        N, Cin, D, H, W = x.shape
        k = weight.shape[-1]
        stride = self.conv_transpose3d.stride[0]
        padding = self.conv_transpose3d.padding[0]
        output_padding = self.conv_transpose3d.output_padding[0]
        groups = self.conv_transpose3d.groups
        Cout = self.conv_transpose3d.out_channels

        Do = (D - 1) * stride - 2 * padding + k + output_padding
        Ho = (H - 1) * stride - 2 * padding + k + output_padding
        Wo = (W - 1) * stride - 2 * padding + k + output_padding

        y = torch.empty((N, Cout, Do, Ho, Wo), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        block_x = 64
        grid_x = (Wo + block_x - 1) // block_x
        grid_y = Ho
        grid_z = N * Cout * Do

        module.launch(
            "convtrans3d_fwd",
            grid=(int(grid_x), int(grid_y), int(grid_z)),
            block=(int(block_x), 1, 1),
            arguments=[
                x,
                weight,
                bias if bias is not None else u64(0),
                y,
                i32(N),
                i32(Cin),
                i32(Cout),
                i32(D),
                i32(H),
                i32(W),
                i32(Do),
                i32(Ho),
                i32(Wo),
                i32(k),
                i32(stride),
                i32(padding),
                i32(output_padding),
                i32(groups),
                i32(1 if bias is not None else 0),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

